// stores/store.js
import { createStore } from "vuex";
import axios from "axios";

const store = createStore({
  state: {
    user: null, // 存储用户信息
  },
  mutations: {
    setUser(state, user) {
      state.user = user; // 设置用户信息
      console.log("设置用户信息:", user); // 确认设置的用户数据
    },
  },
  actions: {
    async login({ commit }, credentials) {
      try {
        // 调用后端 API 进行登录
        const response = await axios.post(
            "http://localhost:5000/api/auth/login",
            credentials,
        );
        console.log("登录响应:", response.data.user); // 打印响应
        commit("setUser", response.data.user); // 存储用户信息
      } catch (error) {
        console.error("登录失败", error);
        // 可以在这里处理登录失败的情况，比如更新状态或显示错误信息
      }
    },
  },
  getters: {
    userId(state) {
      return state.user ? state.user.id : null; // 获取用户 ID
    },
    userNickname(state) {
      return state.user ? state.user.nickname : ""; // 获取用户昵称
    },
  },
});

export default store;
